{
  "requirement_items": [
    {
      "section": "5.4.3.2",
      "label": "[REQ-1-OAD-9503]",
      "text": "Two copies of all data objects covered by [REQ-1-OAD-9370] shall be kept in physically separate locations.",
      "id": "REQ-1-OAD-9503"
    },
    {
      "section": "5.4.3.2",
      "label": null,
      "text": "The physical separation must be large enough that local catastrophic events do not destroy both data copies.",
      "id": null
    },
    {
      "section": "5.4.3.2",
      "label": "[REQ-1-OAD-9506]",
      "text": "Functionality shall be provided to guarantee or automatically and regularly check that the two data copies are identical.",
      "id": "REQ-1-OAD-9506"
    },
    {
      "section": "5.4.3.2",
      "label": "[REQ-1-OAD-9371]",
      "text": "The DMS shall ensure that science data and other science data products covered by the proprietary period policy is secure and not available to unauthorized users or staff from the time it is created until it is public.",
      "id": "REQ-1-OAD-9371"
    },
    {
      "section": "5.4.3.2",
      "label": "[REQ-1-OAD-9376]",
      "text": "The DMS shall provide a database or other system that allows association of science datasets and calibrations as well as associations with other files such as Adaptive Optics Point Spread Function files.",
      "id": "REQ-1-OAD-9376"
    },
    {
      "section": "5.4.3.2",
      "label": "[REQ-1-OAD-9816]",
      "text": "The DMS storage functionality shall use the Single Sign-on Service to authenticate and authorize user identity and roles to ensure users can only access data for which they are entitled.",
      "id": "REQ-1-OAD-9816"
    },
    {
      "section": "5.4.3.3",
      "label": "[REQ-1-OAD-9372]",
      "text": "The DMS shall provide functionality that provides users with access to and retrieval capabilities for data packages associated with their observations and science programs.",
      "id": "REQ-1-OAD-9372"
    },
    {
      "section": "5.4.3.3",
      "label": "[REQ-1-OAD-9374]",
      "text": "The DMS shall provide a minimal access capability that allows the TMT users, technical staff, partners and the public with local and remote access to TMT data products.",
      "id": "REQ-1-OAD-9374"
    },
    {
      "section": "5.4.3.3",
      "label": "[REQ-1-OAD-9810]",
      "text": "The DMS data access functionality shall provide access to TMT data products according to the TMT proprietary period policies.",
      "id": "REQ-1-OAD-9810"
    },
    {
      "section": "5.4.3.3",
      "label": "[REQ-1-OAD-9814]",
      "text": "The DMS access functionality shall use the CSW Single Sign-on Service to authenticate and authorize user roles and set data access rights.",
      "id": "REQ-1-OAD-9814"
    },
    {
      "section": "5.4.3.4",
      "label": null,
      "text": "Data Management System must also collect, store and provide tools for monitoring engineering telemetry.",
      "id": null
    },
    {
      "section": "5.4.3.4",
      "label": "[REQ-1-OAD-9378]",
      "text": "The DMS shall provide a subsystem that captures and stores engineering events (time-stamped) or event streams and provides tools that allow TMT staff to perform simple time-based queries and extract data for further analysis.",
      "id": "REQ-1-OAD-9378"
    },
    {
      "section": "5.4.3.4",
      "label": null,
      "text": "For this reason, the system shall support extraction of data to formats recognizable by these tools.",
      "id": null
    },
    {
      "section": "5.4.3.4",
      "label": "[REQ-1-OAD-9822]",
      "text": "The Engineering Database must support the steady state events and telemetry data rates of Appendix A.3 in the OpsRD (RD35).",
      "id": "REQ-1-OAD-9822"
    },
    {
      "section": "5.4.3.4",
      "label": "[REQ-1-OAD-9823]",
      "text": "The Engineering Database shall be able to capture short bursts of high-bandwidth telemetry according to [REQ-1-OCD-2375].",
      "id": "REQ-1-OAD-9823"
    },
    {
      "section": "5.4.3.4",
      "label": "[REQ-1-OAD-9824]",
      "text": "The set of telemetry that is persisted in the Engineering Database shall be selected during operations, but is assumed to be a subset of the available telemetry.",
      "id": "REQ-1-OAD-9824"
    },
    {
      "section": "5.4.3.4",
      "label": "[REQ-1-OAD-9826]",
      "text": "The storage system and backup strategy defined for science data shall also be used for the Engineering Database storage.",
      "id": "REQ-1-OAD-9826"
    },
    {
      "section": "5.4.3.4",
      "label": "[REQ-1-OAD-9828]",
      "text": "The Engineering Database shall provide an access user interface that allows time-based range queries on a subset of stored telemetry items.",
      "id": "REQ-1-OAD-9828"
    },
    {
      "section": "5.4.3.4",
      "label": null,
      "text": "The list of query items shall be user selectable at query time.",
      "id": null
    },
    {
      "section": "5.4.3.4",
      "label": null,
      "text": "It shall be possible to download results in common formats for analysis in familiar desktop tools.",
      "id": null
    },
    {
      "section": "5.4.3.4",
      "label": "[REQ-1-OAD-9830]",
      "text": "The Engineering Database shall include the ability to generate daily reports of telemetry trends for the purpose of monitoring technical performance.",
      "id": "REQ-1-OAD-9830"
    }
  ],
  "identifier_declarations": [],
  "allocation_entries": []
}
